<script setup lang="ts">import {ref,onMounted} from 'vue';import {go} from '../router';import {studies} from '../stores/studies';import {datasets} from '../stores/datasets';import {instruments} from '../stores/instruments';import {runs} from '../stores/runs';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),dataset=ref('demo-dataset'),instrument=ref('demo-instrument'),ratio=ref(2.25),tolerance=ref(2);const {error,busy,act}=useTask();onMounted(()=>Promise.all([studies.load(),datasets.load(),instruments.load()]));function submit(){act(async()=>{await studies.create({name:name.value,dataset_id:dataset.value,instrument_id:instrument.value,variance_ratio:ratio.value,tolerance:tolerance.value});name.value=''})}function execute(id:string){act(async()=>{const run=await runs.create({study_id:id});go('/results?run='+run.id)})}</script><template><PageHeading index="03 / 研究设定" title="误差方差比，是输入，不是拟合结论。" note="λ=var(y测量误差)/var(x测量误差)，由外部重复测量或计量依据提供。讨论容差不改变BA界限。"/><Notice :message="error"/><div class="two-col"><section><article v-for="r in studies.items.value" :key="r.id" class="study-row"><p class="eyebrow">CALIBRATION STUDY</p><h2>{{r.name}}</h2><dl><div><dt>方差比 λ</dt><dd>{{r.variance_ratio}}</dd></div><div><dt>讨论容差 ±</dt><dd>{{r.tolerance}}</dd></div><div><dt>BA样本SD</dt><dd>ddof=1</dd></div></dl><button v-if="canWrite()" :disabled="busy" @click="execute(r.id)">执行后台校准 →</button></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>新建校准研究</h2><label>研究名称<input v-model="name" required minlength="2"></label><label>配对批次<select v-model="dataset"><option v-for="r in datasets.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>探头组合<select v-model="instrument"><option v-for="r in instruments.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>误差方差比 λ<input type="number" v-model.number="ratio" min=".000001" max="1000000" step="any" required></label><label>讨论容差（同读数单位）<input type="number" v-model.number="tolerance" min=".000001" max="1000000" step="any" required></label><button :disabled="busy">保存研究设定</button></form></div></template>
